CREATE OR REPLACE TRIGGER TRG_INS_UPD_TGQRNC
BEFORE INSERT OR UPDATE ON TGQRNC FOR EACH ROW
BEGIN

 IF (inserting) THEN

 	:NEW.FASESNCID := 1;
    :NEW.DATAREGISTRO := SYSDATE;

    :NEW.DATAPREVENCERRAR := :NEW.DATAREGISTRO + 60;

 END IF;

 IF (:OLD.FASESNCID <> :NEW.FASESNCID) THEN

     INSERT INTO TGQREGFASES (RNCID, IDREGFASES, FASESNCID, DATAFASE, CODUSU)
	 VALUES (:NEW.RNCID, SEQ_TGQREGFASES.NEXTVAL, :NEW.FASESNCID, SYSDATE, STP_GET_CODUSULOGADO());

 END IF;

END;

CREATE OR REPLACE TRIGGER TRG_STATUS_TGQCAUSARAIZ
BEFORE INSERT OR UPDATE ON TGQCAUSARAIZ FOR EACH ROW
BEGIN
    IF INSERTING THEN
        :NEW.STATUS := 'E';
        IF :NEW.DATAPRAZO IS NULL THEN
            SELECT R.DATAREGISTRO + 7 INTO :NEW.DATAPRAZO FROM TGQRNC R WHERE R.RNCID = :NEW.RNCID;
        END IF;
    ELSIF UPDATING THEN
        IF :NEW.CONCLUIDO = 'S' THEN
            :NEW.STATUS := 'C';
        END IF;
    END IF;
END;

