CREATE OR REPLACE TRIGGER TRG_PRAZO_TGQVEREFICACIA
BEFORE INSERT ON TGQVEREFICACIA FOR EACH ROW
BEGIN
    IF :NEW.DATAPRAZO IS NULL THEN
        SELECT R.DATAREGISTRO + 60 INTO :NEW.DATAPRAZO FROM TGQRNC R WHERE R.RNCID = :NEW.RNCID;
    END IF;
END;
